(()=>{'use strict';
const page=document.getElementById('page-academy');
if(!page||window.__adazStudyStudio)return;
window.__adazStudyStudio=true;
const KEY='adaz-study-studio-v1';
const $=(s,r=page)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const dateText=s=>{try{return new Date((s||today())+'T12:00:00').toLocaleDateString('es-CO',{day:'numeric',month:'short'})}catch{return s||''}};
const read=(k,f)=>{try{const v=JSON.parse(localStorage.getItem(k)||'null');return v&&typeof v==='object'?v:f}catch{return f}};
const initial={done:{},lastCourse:'icfes',current:null,drafts:{},working:{}};
let state=read(KEY,initial);
state.done=state.done&&typeof state.done==='object'?state.done:{};
state.drafts=state.drafts&&typeof state.drafts==='object'?state.drafts:{};
state.working=state.working&&typeof state.working==='object'?state.working:{};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('No se pudo guardar el avance de Estudio',e)}}
const courses=[
{id:'business',title:'Negocio · Oro Laminado',short:'Oro Laminado',icon:'✧',desc:'Aprende a elegir mejor, calcular costos, vender con claridad y cuidar cada pedido.',goal:'Convertir tu negocio en un proceso ordenado, rentable y confiable.',lessons:[
{id:'b1',title:'Conoce exactamente lo que vendes',time:12,blocks:[['La ficha de cada producto','Antes de publicar una pieza, reúne la información que puedes demostrar: material de base, tipo de recubrimiento, acabado, medidas, peso si está disponible, cuidados, garantía y condiciones del proveedor. No conviertas una frase comercial en una especificación técnica.'],['Qué pedir al proveedor','Solicita ficha técnica, descripción del proceso, condiciones de garantía por tipo de pieza, comprobante de compra y política para cambios o defectos. Conserva la respuesta escrita.'],['Cómo hablar con honestidad','Describe el producto tal como está documentado. Si no conoces el espesor del recubrimiento, no inventes micras. Si hay diferencias entre modelos, explícalas antes de cobrar.']],example:'Una publicación dice «oro 18K garantizado» pero el proveedor no entrega ficha técnica ni aclara qué cubre su garantía. Lo responsable es pedir la documentación y no prometer una duración que no está demostrada.',quiz:[{q:'¿Qué haces antes de afirmar una especificación técnica?',opts:['La deduces por el color','Pides documentación verificable al proveedor','Copias lo que dice otra tienda'],a:1,why:'Una afirmación técnica debe apoyarse en información verificable del producto y del proveedor.'},{q:'La garantía cambia entre tipos de piezas. ¿Cómo lo comunicas?',opts:['Usas una promesa general para todas','No mencionas ninguna condición','Explicas por escrito qué cubre cada tipo'],a:2,why:'Una política clara evita promesas ambiguas y ayuda al cliente a decidir con información.'}]},
{id:'b2',title:'Calcula cuánto te cuesta una pieza',time:15,blocks:[['El costo no es solo el precio del proveedor','Incluye el costo de compra, la parte proporcional del envío, empaque, comisiones de pago y otros gastos necesarios para entregar el pedido. Separa los costos del negocio de los gastos personales.'],['Ejemplo sencillo','Una pieza cuesta $48.000. El envío que le corresponde suma $4.000 y el empaque $2.000. El costo registrado de esa pieza es $54.000, antes de otros gastos que puedan aplicar.'],['Registra cada cifra','Anota la fecha, proveedor, referencia, cantidad, costo y comprobante. Cuando compres varias referencias en un mismo envío, define un criterio consistente para repartirlo.']],example:'Costo unitario = compra + envío asignado + empaque + otros costos directos. Si falta un dato, déjalo como pendiente; no lo reemplaces con una cifra inventada.',quiz:[{q:'Compras una pieza por $48.000, su parte del envío cuesta $4.000 y el empaque $2.000. ¿Qué costo directo registras?',opts:['$48.000','$52.000','$54.000'],a:2,why:'48.000 + 4.000 + 2.000 = 54.000. Registrar el costo completo evita creer que la ganancia es mayor de lo real.'},{q:'No sabes todavía cuánto costó un envío compartido. ¿Qué haces?',opts:['Lo ignoras','Lo marcas pendiente y defines cómo repartirlo','Duplicas el precio del producto'],a:1,why:'Una cifra pendiente es más honesta y útil que una estimación disfrazada de dato real.'}]},
{id:'b3',title:'Pon un precio con sentido',time:14,blocks:[['Ganancia y margen no son lo mismo','La ganancia bruta es el precio de venta menos el costo. El margen bruto es esa ganancia dividida por el precio de venta. El recargo sobre costo se calcula de otra manera.'],['Ejemplo para entender el margen','Si el costo es $54.000 y el precio es $90.000, la diferencia es $36.000. El margen bruto es 40% porque 36.000 ÷ 90.000 = 0,40. Aún debes considerar gastos generales, impuestos que correspondan y otros costos.'],['Compara antes de publicar','Revisa precios de piezas comparables, valor percibido, calidad demostrable, costos y capacidad de cumplir. No bajes el precio por impulso sin revisar el margen.']],example:'Margen bruto = (precio − costo) ÷ precio. No es una recomendación automática de precio: sirve para analizar escenarios con tus datos reales.',quiz:[{q:'Una pieza cuesta $54.000 y se vende por $90.000. ¿Cuál es la ganancia bruta antes de otros gastos?',opts:['$36.000','$54.000','$90.000'],a:0,why:'La diferencia entre precio y costo es 36.000 pesos.'},{q:'¿Cómo calculas el margen bruto del ejemplo?',opts:['36.000 ÷ 54.000','36.000 ÷ 90.000','90.000 ÷ 36.000'],a:1,why:'El margen se divide entre el precio de venta, no entre el costo.'}]},
{id:'b4',title:'Organiza un pedido por encargo',time:13,blocks:[['Un pedido tiene etapas','Consulta, confirmación de referencia, cotización, condiciones por escrito, anticipo si se acuerda, compra al proveedor, revisión al recibir, entrega y seguimiento.'],['Antes de recibir dinero','Confirma el modelo, precio total, qué incluye, fecha estimada, forma de pago, política si el proveedor no entrega y qué ocurre si el cliente cambia de opinión. La condición debe ser clara y aceptada por ambas partes.'],['Seguimiento simple','Cada pedido necesita un estado: consulta, pendiente de confirmación, confirmado, solicitado al proveedor, recibido, listo para entregar o finalizado. No prometas una fecha que no controlas.']],example:'Un cliente pide una pulsera que no tienes disponible. Antes de tomar un anticipo, confirmas proveedor, referencia, precio, plazo estimado y condiciones. Luego le envías un resumen escrito.',quiz:[{q:'¿Cuándo conviene confirmar el pedido?',opts:['Después de aclarar referencia, precio, plazo y condiciones','Solo cuando el proveedor envía el paquete','Sin escribir nada para hacerlo rápido'],a:0,why:'La confirmación escrita reduce errores y alinea expectativas.'},{q:'El proveedor retrasa la entrega. ¿Qué haces?',opts:['Dejas de responder','Informas el cambio, das una nueva estimación y explicas las opciones','Prometes que llegará mañana sin confirmarlo'],a:1,why:'La comunicación temprana y honesta protege la confianza.'}]},
{id:'b5',title:'Crea un catálogo que dé confianza',time:12,blocks:[['Una foto, una idea','Usa luz uniforme, fondo limpio, enfoque nítido y una imagen que muestre la pieza completa. Añade una segunda foto para enseñar el cierre, textura o escala.'],['Información que debe verse','Nombre o referencia, material según ficha, medidas, precio o forma de cotización, disponibilidad, plazo de encargo y cuidados. Evita saturar la imagen con texto.'],['Contenido útil','Alterna producto, detalle, cuidados, proceso real y respuestas a preguntas frecuentes. No uses fotos de proveedor como si fueran fotografías propias.']],example:'Una ficha clara responde en pocos segundos: qué es, cómo se ve, cuánto cuesta, cuándo estaría disponible y qué información respalda su descripción.',quiz:[{q:'¿Qué imagen ayuda más a decidir?',opts:['Una foto oscura con muchos filtros','Una foto nítida del producto y otra de sus detalles','Una imagen de otra referencia parecida'],a:1,why:'Las fotografías reales y claras reducen la incertidumbre y evitan confusiones entre referencias.'},{q:'¿Qué información debe acompañar una pieza por encargo?',opts:['Solo «escríbeme»','Disponibilidad y plazo estimado, además de precio y detalles','Una promesa de entrega inmediata'],a:1,why:'El cliente necesita conocer precio, características y plazo antes de confirmar.'}]},
{id:'b6',title:'Atiende y fideliza sin improvisar',time:12,blocks:[['Respuesta útil','Saluda, responde la pregunta concreta, comparte datos verificables y cierra con un siguiente paso. Si no sabes algo, dilo y confirma antes de contestar.'],['Después de la venta','Confirma la entrega, comparte cuidados del producto y recuerda las condiciones reales de garantía. Guarda el seguimiento sin exponer datos personales.'],['Mide lo que sí sirve','Revisa cuántas consultas llegan, cuántas se convierten en pedidos, qué referencias se venden, cuánto queda después de costos y qué problemas se repiten.']],example:'No basta con contar seguidores. Un catálogo con menos visitas pero consultas claras y pedidos rentables puede ser más valioso.',quiz:[{q:'¿Qué dato ayuda a saber si el catálogo convierte?',opts:['Solo los seguidores','Consultas que terminan en pedidos','Cantidad de publicaciones sin contexto'],a:1,why:'Relacionar consultas y pedidos muestra mejor si el contenido lleva a una compra.'},{q:'¿Qué haces si desconoces una característica?',opts:['La inventas para cerrar la venta','La confirmas con el proveedor antes de prometer','Evitas toda pregunta del cliente'],a:1,why:'Es preferible verificar una información antes que crear una expectativa falsa.'}]}
]},
{id:'medicine',title:'Medicina · Bases preuniversitarias',short:'Medicina',icon:'＋',color:'blue',desc:'Construye bases de biología, anatomía y fisiología para acercarte a la carrera.',goal:'Comprender cómo se organiza y funciona el cuerpo humano.',lessons:[
{id:'m1',title:'Cómo se organiza el cuerpo humano',time:12,blocks:[['De lo pequeño a lo grande','El cuerpo se puede estudiar por niveles: moléculas, células, tejidos, órganos, sistemas y organismo. Cada nivel tiene propiedades que dependen de la organización del nivel anterior.'],['Ejemplo: el corazón','Las células musculares cardíacas forman tejido; distintos tejidos se organizan en el corazón; el corazón trabaja con vasos sanguíneos y sangre dentro del sistema cardiovascular.'],['Una idea clave','No estudies los órganos como piezas aisladas: pregunta qué estructura tienen, qué función cumplen y con qué sistemas trabajan.']],example:'Células musculares → tejido muscular cardíaco → corazón → sistema cardiovascular → organismo.',quiz:[{q:'¿Qué nivel está formado por varios tejidos que cumplen una función?',opts:['Molécula','Órgano','Célula'],a:1,why:'Un órgano reúne diferentes tejidos que trabajan juntos.'},{q:'¿Cuál es el orden correcto, de menor a mayor?',opts:['Órgano, célula, tejido, sistema','Célula, tejido, órgano, sistema','Sistema, tejido, célula, órgano'],a:1,why:'Las células forman tejidos; los tejidos forman órganos; los órganos integran sistemas.'}]},
{id:'m2',title:'La célula: unidad básica de la vida',time:15,blocks:[['Membrana y citoplasma','La membrana separa el interior celular del medio y regula el intercambio. El citoplasma contiene agua, moléculas y estructuras celulares.'],['Organelos principales','El núcleo guarda la mayor parte del ADN. Las mitocondrias participan en la producción de ATP. Los ribosomas ensamblan proteínas. El retículo endoplasmático y el aparato de Golgi participan en su procesamiento y transporte.'],['Especialización','Las células no son idénticas: su forma y sus componentes se relacionan con las tareas que realizan.']],example:'Una célula muscular necesita mucha energía para contraerse; por eso suele tener numerosas mitocondrias.',quiz:[{q:'¿Qué estructura regula buena parte del intercambio entre la célula y su entorno?',opts:['Membrana plasmática','Núcleo','Ribosoma'],a:0,why:'La membrana funciona como barrera selectiva y regula el transporte.'},{q:'¿Qué organelo participa en la producción de ATP?',opts:['Aparato de Golgi','Mitocondria','Lisosoma'],a:1,why:'Las mitocondrias producen gran parte del ATP en células eucariotas.'}]},
{id:'m3',title:'Los cuatro tejidos básicos',time:14,blocks:[['Epitelial','Cubre superficies, reviste cavidades y forma glándulas. Participa en protección, absorción y secreción.'],['Conectivo','Une, sostiene y protege. Incluye ejemplos como hueso, cartílago, sangre y tejido adiposo.'],['Muscular y nervioso','El tejido muscular se contrae y produce movimiento. El nervioso recibe, procesa y transmite información mediante neuronas y células de apoyo.']],example:'La pared intestinal combina epitelio para absorber, tejido conectivo para sostener, músculo para mover el contenido y tejido nervioso para coordinar actividad.',quiz:[{q:'¿Qué tejido está especializado en contraerse?',opts:['Conectivo','Muscular','Epitelial'],a:1,why:'La contracción es la función característica del tejido muscular.'},{q:'¿Cuál es un ejemplo de tejido conectivo?',opts:['Sangre','Epidermis','Tejido nervioso'],a:0,why:'La sangre se clasifica como tejido conectivo especializado.'}]},
{id:'m4',title:'Homeostasis: mantener el equilibrio interno',time:15,blocks:[['Qué significa','Homeostasis es la regulación de condiciones internas, como temperatura, glucosa, agua y pH, dentro de rangos compatibles con la función del organismo. No significa que todo permanezca inmóvil.'],['Retroalimentación negativa','Un cambio activa respuestas que tienden a reducir ese cambio. Por ejemplo, cuando sube la temperatura corporal, mecanismos como la sudoración ayudan a disipar calor.'],['Retroalimentación positiva','En ciertos procesos, la respuesta amplifica el estímulo hasta completar un evento. Es un mecanismo distinto y se utiliza solo en situaciones reguladas.']],example:'Sube la temperatura → el cuerpo activa respuestas para liberar calor → la temperatura tiende a regresar hacia su rango habitual.',quiz:[{q:'La sudoración cuando aumenta la temperatura es un ejemplo de:',opts:['Retroalimentación negativa','Retroalimentación positiva','Ausencia de regulación'],a:0,why:'La respuesta contrarresta el aumento inicial de temperatura.'},{q:'¿Homeostasis significa que el cuerpo nunca cambia?',opts:['Sí, todo debe quedar fijo','No, regula variables dinámicas dentro de rangos','Solo ocurre durante el sueño'],a:1,why:'El cuerpo cambia continuamente y regula sus variables.'}]},
{id:'m5',title:'Posición anatómica y términos de orientación',time:14,blocks:[['La referencia común','La posición anatómica describe una postura de referencia: cuerpo erguido, mirada al frente, brazos a los lados y palmas orientadas hacia adelante. Se usa para que las descripciones no dependan de cómo esté acostada una persona.'],['Términos direccionales','Superior significa hacia la cabeza; inferior hacia los pies; anterior hacia el frente; posterior hacia atrás; medial hacia la línea media y lateral alejándose de ella.'],['Planos anatómicos','El plano sagital divide derecha e izquierda; el frontal divide anterior y posterior; el transversal divide superior e inferior.']],example:'El esternón está anterior al corazón. El corazón está medial respecto a los pulmones.',quiz:[{q:'¿Qué plano divide el cuerpo en partes superior e inferior?',opts:['Sagital','Frontal','Transversal'],a:2,why:'El plano transversal separa porciones superior e inferior.'},{q:'Respecto a los pulmones, el corazón está principalmente:',opts:['Medial','Lateral','Inferior'],a:0,why:'El corazón se ubica entre los pulmones, cerca de la línea media.'}]},
{id:'m6',title:'Sistema cardiovascular: recorrido de la sangre',time:15,blocks:[['La bomba y las vías','El corazón impulsa sangre por vasos. Las arterias llevan sangre desde el corazón; las venas la devuelven al corazón; los capilares permiten intercambio con los tejidos.'],['Dos circuitos','La circulación pulmonar lleva sangre del lado derecho del corazón a los pulmones y vuelve al lado izquierdo. La circulación sistémica lleva sangre del lado izquierdo al cuerpo y regresa al lado derecho.'],['El sentido importa','Arteria no significa siempre sangre rica en oxígeno: se define por la dirección del flujo, no por el contenido de oxígeno.']],example:'Ventrículo derecho → arterias pulmonares → pulmones → venas pulmonares → aurícula izquierda.',quiz:[{q:'¿Qué define a una arteria?',opts:['Lleva sangre hacia el corazón','Lleva sangre desde el corazón','Siempre transporta sangre oxigenada'],a:1,why:'La definición depende de la dirección del flujo.'},{q:'¿Qué circuito lleva sangre a los pulmones?',opts:['Sistémico','Portal','Pulmonar'],a:2,why:'La circulación pulmonar conecta el corazón con los pulmones.'}]},
{id:'m7',title:'Sistema respiratorio e intercambio de gases',time:15,blocks:[['Ventilación e intercambio','Ventilar es mover aire dentro y fuera de los pulmones. El intercambio gaseoso ocurre en los alvéolos, donde oxígeno y dióxido de carbono difunden entre aire y sangre.'],['Transporte','La sangre transporta la mayor parte del oxígeno unido a hemoglobina dentro de los glóbulos rojos. El dióxido de carbono viaja por varias formas, principalmente como bicarbonato.'],['Respirar no es solo inhalar','La respiración celular usa oxígeno en procesos metabólicos para obtener energía química utilizable; ocurre dentro de las células, no en los pulmones.']],example:'Aire llega a alvéolos → oxígeno difunde hacia la sangre → la sangre lo lleva a tejidos → dióxido de carbono vuelve a los pulmones.',quiz:[{q:'¿Dónde ocurre el intercambio de gases entre aire y sangre?',opts:['Alvéolos','Tráquea','Laringe'],a:0,why:'Los alvéolos ofrecen una superficie delgada y amplia para la difusión.'},{q:'¿Dónde ocurre la respiración celular?',opts:['Solo en la nariz','En las células','En los alvéolos únicamente'],a:1,why:'La respiración celular es un conjunto de procesos metabólicos celulares.'}]},
{id:'m8',title:'Bioquímica básica: energía y enzimas',time:16,blocks:[['Moléculas de la vida','Carbohidratos, lípidos, proteínas y ácidos nucleicos cumplen funciones distintas. Aportan energía, forman estructuras, regulan procesos y almacenan información.'],['ATP','El ATP es una molécula que transfiere energía utilizable para muchos procesos celulares. Se produce y consume continuamente.'],['Enzimas','Las enzimas aceleran reacciones químicas al reducir la energía de activación. Son específicas y su actividad puede cambiar con temperatura, pH y concentración de sustrato.']],example:'Una enzima digestiva facilita la ruptura de ciertos enlaces en moléculas de alimentos. No convierte cualquier sustancia en cualquier otra: tiene especificidad.',quiz:[{q:'¿Cuál es el papel principal de una enzima?',opts:['Acelerar una reacción sin consumirse como reactivo','Almacenar toda la información genética','Formar siempre membranas'],a:0,why:'Las enzimas son catalizadores biológicos.'},{q:'¿Qué molécula participa en transferir energía dentro de la célula?',opts:['ADN','ATP','Celulosa'],a:1,why:'El ATP funciona como una fuente inmediata de energía para procesos celulares.'}]}
]},
{id:'icfes',title:'ICFES · Saber 11',short:'Saber 11',icon:'◎',color:'violet',desc:'Entrena las cinco áreas con situaciones, razonamiento y revisión de errores.',goal:'Aprender a interpretar la situación y justificar cada respuesta.',official:'https://www.icfes.gov.co/caja-de-herramientas-saber-11/practica/',lessons:[
{id:'i1',title:'Lectura crítica: encuentra la idea y la evidencia',time:15,blocks:[['Lee con una pregunta','Antes de elegir, identifica qué pide el enunciado: idea principal, inferencia, intención, relación entre partes o evaluación de un argumento.'],['Distingue afirmación y evidencia','La respuesta correcta debe apoyarse en el texto. Una opción puede sonar razonable, pero ser incorrecta si añade información que el autor no afirma ni permite inferir.'],['Revisa los distractores','Descarta opciones demasiado amplias, absolutas o que cambian el sentido de una palabra clave.']],example:'Texto original ADAZ: «La biblioteca amplió su horario. Durante el primer mes recibió más visitantes, pero aún no evaluó el efecto en las notas». No puedes concluir que las notas mejoraron.',quiz:[{q:'¿Qué conclusión está respaldada por el texto?',opts:['Las notas mejoraron','Aumentaron los visitantes durante el primer mes','La biblioteca comprobó mejores resultados'],a:1,why:'El texto informa más visitantes, pero aclara que no se midió el efecto en las notas.'},{q:'Una opción agrega un dato que el texto no menciona. ¿Qué haces?',opts:['La eliges porque parece lógica','La descartas si la pregunta exige evidencia textual','La eliges si es más larga'],a:1,why:'La inferencia debe estar respaldada; no se completa el texto con suposiciones.'}]},
{id:'i2',title:'Matemáticas: porcentajes y proporciones',time:16,blocks:[['Traduce el problema','Subraya cantidades, unidades, relación y qué debes encontrar. Decide si necesitas sumar, comparar, hallar una parte o calcular un cambio porcentual.'],['Porcentaje como parte de cien','15% significa 15 de cada 100. Para hallar el 15% de 80, calcula 0,15 × 80 = 12. Para aumentar 80 en 15%, calcula 80 × 1,15 = 92.'],['Comprueba si la respuesta tiene sentido','Estima el resultado y revisa unidades. Un descuento debe reducir el precio; un aumento debe elevarlo.']],example:'Una entrada cuesta $80.000 y aumenta 15%. El nuevo precio es 80.000 × 1,15 = $92.000.',quiz:[{q:'¿Cuánto es el 20% de 150?',opts:['20','30','45'],a:1,why:'0,20 × 150 = 30.'},{q:'Un valor de 200 aumenta 10%. ¿Cuál es el nuevo valor?',opts:['190','210','220'],a:2,why:'10% de 200 es 20; 200 + 20 = 220.'}]},
{id:'i3',title:'Ciencias naturales: piensa como investigador',time:16,blocks:[['Pregunta e hipótesis','Una investigación comienza con una pregunta que pueda estudiarse. La hipótesis es una explicación provisional que puede ponerse a prueba.'],['Variables','La variable independiente es la que se modifica; la dependiente es la que se mide; las variables controladas se mantienen constantes para interpretar mejor el resultado.'],['Lee los datos antes de concluir','Una asociación no demuestra por sí sola causalidad. Observa el diseño, el tamaño de la muestra, las mediciones y las limitaciones.']],example:'Se comparan plantas con distinta cantidad de luz y se mide su crecimiento. La luz es la variable independiente; el crecimiento es la dependiente.',quiz:[{q:'En ese experimento, ¿qué variable se mide?',opts:['Cantidad de luz','Crecimiento de la planta','Tipo de regla'],a:1,why:'El crecimiento es el resultado que se registra: la variable dependiente.'},{q:'¿Por qué se mantienen iguales el agua y el tipo de suelo?',opts:['Para controlar otras variables','Para cambiar dos factores a la vez','Para evitar medir el crecimiento'],a:0,why:'Controlar factores ayuda a atribuir los cambios al factor investigado.'}]},
{id:'i4',title:'Sociales: contrasta fuentes y perspectivas',time:15,blocks:[['Ubica la fuente','Pregunta quién produce el documento, cuándo, con qué propósito y para qué público. Una fuente puede aportar información y también tener una perspectiva particular.'],['Compara antes de aceptar','Contrasta fuentes independientes, identifica coincidencias y diferencias y separa hechos, opiniones e interpretaciones.'],['Contextualiza','Una afirmación puede cambiar de sentido según el momento histórico, el lugar, los actores y las condiciones sociales.']],example:'Dos periódicos informan sobre una reforma. Uno entrevista a trabajadores y otro a empresarios. Compararlos ayuda a reconocer perspectivas, no a asumir que uno es automáticamente falso.',quiz:[{q:'¿Qué dato ayuda a evaluar una fuente histórica?',opts:['Autor, fecha y propósito','Solo el color del documento','La cantidad de palabras'],a:0,why:'La autoría, el contexto y el propósito ayudan a interpretar su alcance y sesgos.'},{q:'Dos fuentes describen un hecho de manera diferente. ¿Qué paso es mejor?',opts:['Elegir la más emocional','Comparar evidencia, contexto y propósito','Ignorar ambas'],a:1,why:'El contraste razonado ayuda a reconocer diferencias de perspectiva y de evidencia.'}]},
{id:'i5',title:'Inglés ICFES: usa el contexto',time:14,blocks:[['No traduzcas palabra por palabra','Lee la frase completa, identifica quién habla, para quién y con qué propósito. Las palabras cercanas suelen dar pistas sobre el significado.'],['Reconoce conectores','But introduce contraste; because una razón; therefore una consecuencia; although una concesión. Los conectores muestran cómo se relacionan las ideas.'],['Comprueba la opción','La respuesta debe encajar en gramática, sentido y contexto. No elijas solo porque reconoces una palabra.']],example:'«The road was closed; therefore, the bus arrived late». Therefore presenta una consecuencia: el cierre de la vía explica la demora.',quiz:[{q:'In «Maya studied carefully because the test was difficult», what does because introduce?',opts:['A reason','A contrast','A result'],a:0,why:'Because introduces the reason Maya studied carefully.'},{q:'In «The shop was small; however, it was easy to find», however shows:',opts:['Addition','Contrast','Cause'],a:1,why:'However introduces a contrast between size and ease of finding the shop.'}]}
]},
{id:'ielts',title:'IELTS Academic · Band 8',short:'IELTS',icon:'A',color:'green',desc:'Mejora las cuatro habilidades con tareas, estrategias y revisión clara.',goal:'Construir un rendimiento sólido y equilibrado hacia Band 8.',official:'https://www.ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test',lessons:[
{id:'e1',title:'Listening: predice y detecta cambios',time:15,audio:'I originally planned to meet the tutor on Tuesday afternoon, but the laboratory is unavailable then. We agreed to meet on Thursday at ten instead.',blocks:[['Antes de escuchar','Lee el contexto y predice qué información falta: fecha, nombre, lugar, cantidad o razón. Esto te ayuda a escuchar con un objetivo.'],['Durante el audio','No te quedes atascado en una palabra. Detecta sinónimos, correcciones y distractores. Una persona puede mencionar una opción y luego cambiarla.'],['Después','Revisa si escribiste la información exacta, incluidos números, plural, ortografía y límite de palabras.']],example:'El hablante menciona Tuesday, pero después corrige el plan. La cita final es Thursday at ten.',quiz:[{q:'What is the final meeting day?',opts:['Tuesday','Thursday','Friday'],a:1,why:'The speaker changes the original Tuesday plan to Thursday.'},{q:'What time is the meeting?',opts:['9:00','10:00','12:00'],a:1,why:'The corrected plan is Thursday at ten.'}]},
{id:'e2',title:'Listening: completa notas con precisión',time:15,audio:'The museum tour begins at nine thirty. Visitors should enter through the south entrance and bring a printed ticket. Large bags must be left in the lockers near reception.',blocks:[['Escucha palabras clave','En formularios y notas, identifica qué categoría falta: hora, dirección, objeto, regla o nombre propio.'],['Respeta la instrucción','Si el ejercicio dice «ONE WORD ONLY», una respuesta de dos palabras puede ser incorrecta aunque la idea sea buena.'],['Comprueba gramática y sonido','Distingue cifras parecidas, singular/plural y palabras que suenan de manera similar.']],example:'Pregunta: «Visitors should enter through the ___ entrance». La información que completa el espacio es «south».',quiz:[{q:'What time does the tour begin?',opts:['9:13','9:30','10:30'],a:1,why:'The recording states nine thirty.'},{q:'Which entrance should visitors use?',opts:['North','Main','South'],a:2,why:'The instruction says to enter through the south entrance.'}]},
{id:'e3',title:'Reading: True, False o Not Given',time:16,blocks:[['True','La afirmación coincide con la información del texto, incluso si usa otras palabras.'],['False','El texto dice algo que contradice la afirmación. Debe existir evidencia contraria, no solo falta de información.'],['Not Given','El texto no confirma ni contradice la afirmación. No completes los vacíos con lo que sabes del mundo.']],example:'Texto original: «The research team collected data in three cities. It plans to publish a second report next year». Afirmación: «The report compares four cities». La cantidad cuatro no aparece ni se contradice: Not Given.',quiz:[{q:'Text: «The survey included 500 students». Statement: «The survey included 500 students».',opts:['True','False','Not Given'],a:0,why:'La afirmación repite la información del texto.'},{q:'Text: «The report will be published next year». Statement: «The report was published last month».',opts:['True','False','Not Given'],a:1,why:'El tiempo verbal y el momento se contradicen.'}]},
{id:'e4',title:'Reading: paráfrasis y localizar evidencia',time:16,blocks:[['No busques solo palabras idénticas','Los textos suelen expresar una idea con vocabulario diferente al de la pregunta. Busca equivalencias de significado, no coincidencias exactas.'],['Lee antes y después','Localiza una palabra clave, lee la oración y su contexto y confirma que la relación responde exactamente a lo preguntado.'],['Evita atajos','Un mismo término puede aparecer en un párrafo irrelevante. La evidencia debe respaldar la respuesta, no solo compartir una palabra.']],example:'Question: «The project was postponed». Text: «The team delayed the launch». Postponed y delayed expresan la misma idea.',quiz:[{q:'Which phrase is closest in meaning to «increased»?',opts:['Went up','Stayed equal','Was removed'],a:0,why:'Went up expresa un aumento.'},{q:'A keyword appears in a paragraph, but the paragraph discusses a different idea. What should you do?',opts:['Choose it immediately','Check the full sentence and surrounding context','Ignore the question'],a:1,why:'La coincidencia léxica no basta; hay que verificar la evidencia contextual.'}]},
{id:'e5',title:'Writing Task 1: escribe una visión general',time:18,write:true,blocks:[['Primero identifica la historia de los datos','Observa tendencias principales, máximos, mínimos, contrastes o etapas. No empieces describiendo cada cifra.'],['La visión general','Escribe una o dos frases que resuman los patrones más importantes sin incluir todos los detalles. Esta parte muestra que comprendiste la información.'],['Después selecciona datos','Compara cifras representativas y usa verbos y expresiones precisas: rose, fell, remained stable, approximately, just over, whereas. No inventes causas.']],example:'Si una gráfica muestra que el uso de bicicleta subió mientras el uso de automóvil bajó, la visión general debe señalar esas dos tendencias sin inventar por qué ocurrieron.',quiz:[{q:'What should the overview mainly do?',opts:['List every number','Summarise the main trends','Explain causes not shown'],a:1,why:'El overview resume los rasgos principales; los datos concretos van en los párrafos de detalle.'},{q:'The chart shows a rise, but gives no explanation. Should you invent a cause?',opts:['Yes, to make it longer','No, describe only what the data supports','Yes, if it sounds likely'],a:1,why:'IELTS Academic Task 1 evalúa descripción precisa; no atribuyas causas que la gráfica no ofrece.'}]},
{id:'e6',title:'Writing Task 2: construye un argumento',time:20,write:true,blocks:[['Responde exactamente','Subraya el tema, el verbo de la consigna y si te pide opinión, discusión, ventajas/desventajas o solución. No escribas un ensayo genérico.'],['Desarrolla cada idea','Usa una idea central, explicación, ejemplo pertinente y vínculo con la pregunta. Dos ideas desarrolladas suelen ser más claras que muchas ideas superficiales.'],['Revisa con criterios','Comprueba respuesta a la consigna, coherencia, vocabulario y variedad/precisión gramatical. Evita memorizar ensayos completos.']],example:'Pregunta original ADAZ: «Should universities include practical work experience in every degree?» Elige una postura, desarrolla dos razones y reconoce un límite o contraargumento.',quiz:[{q:'What makes a body paragraph stronger?',opts:['Several unrelated ideas','One clear idea explained and supported','A memorised sentence unrelated to the prompt'],a:1,why:'Un párrafo desarrollado mantiene una idea central y la respalda.'},{q:'What should you do before writing?',opts:['Identify exactly what the prompt asks','Copy a prepared essay','Start with a memorised introduction'],a:0,why:'El plan debe responder a esa consigna específica.'}]},
{id:'e7',title:'Speaking Part 2: desarrolla una respuesta',time:16,write:true,blocks:[['Organiza tu minuto de preparación','Identifica quién o qué, cuándo, dónde, qué ocurrió y por qué es importante. Elige detalles que puedas explicar con naturalidad.'],['Habla con desarrollo','Expande con una secuencia clara: situación, detalle, ejemplo y reflexión. Usa conectores naturales; no fuerces vocabulario que no dominas.'],['Si te equivocas, continúa','Reformula una frase si lo necesitas. La fluidez no significa hablar sin pausas, sino mantener un discurso comprensible y conectado.']],example:'Tarjeta original ADAZ: Describe una habilidad que te gustaría aprender. Explica qué es, por qué te interesa, cómo la practicarías y cuándo empezarías.',quiz:[{q:'What is a useful way to organise a long-turn answer?',opts:['Situation, details, example and reflection','Memorise four unrelated paragraphs','Repeat the prompt only'],a:0,why:'Una estructura sencilla ayuda a desarrollar el tema sin sonar como un discurso memorizado.'},{q:'You forget one word. What is a good strategy?',opts:['Stop completely','Explain the idea using different words','Repeat the same word louder'],a:1,why:'Paraphrasing mantiene la comunicación y demuestra flexibilidad léxica.'}]},
{id:'e8',title:'Speaking Part 3: analiza y matiza',time:17,write:true,blocks:[['Pasa de lo personal a lo general','Part 3 suele profundizar en ideas más amplias: sociedad, educación, tecnología, cultura o cambios a lo largo del tiempo.'],['Responde y justifica','Da una postura, razón y ejemplo; después matiza con una excepción, una limitación o una perspectiva distinta.'],['Evita respuestas absolutas','Expresiones como «in some cases», «to a certain extent» o «this may depend on» permiten argumentar con precisión.']],example:'Pregunta original ADAZ: «How might technology change the way people learn?» Puedes hablar de acceso, retroalimentación y límites, sin afirmar que toda tecnología mejora el aprendizaje.',quiz:[{q:'Which answer is more developed?',opts:['Technology is good.','Technology can widen access, although results depend on guidance and design.','Everyone uses technology.'],a:1,why:'La segunda respuesta presenta una idea, añade un matiz y evita una afirmación absoluta.'},{q:'What does «to a certain extent» help you do?',opts:['Make an absolute claim','Show a qualified or balanced position','Avoid answering'],a:1,why:'La expresión permite matizar el alcance de una opinión.'}]}
]}
];
const styles=document.createElement('style');
styles.id='adaz-study-studio-style';
styles.textContent=[
'#page-academy{--ss-bg:#0b111b;--ss-card:#121d2c;--ss-line:#29394f;--ss-text:#eef3fa;--ss-muted:#a8b5c8;--ss-accent:#b9d4fb}',
'#page-academy .ss-wrap{max-width:900px;margin:0 auto;color:var(--ss-text)}',
'#page-academy .ss-kicker{font-size:10px;letter-spacing:1.1px;text-transform:uppercase;color:#9fbde6;font-weight:850}',
'#page-academy .ss-title{font-size:clamp(26px,5vw,34px);line-height:1.08;letter-spacing:-1.2px;margin:5px 0 7px}',
'#page-academy .ss-sub{font-size:12px;line-height:1.55;color:var(--ss-muted);margin:0}',
'#page-academy .ss-hero{background:linear-gradient(135deg,#1b2d45,#111a28);border:1px solid #344a65;border-radius:22px;padding:17px;margin:12px 0}',
'#page-academy .ss-hero h2{font-size:19px;line-height:1.2;margin:5px 0}',
'#page-academy .ss-hero p{font-size:12px;color:#bdc9d9;line-height:1.5;margin:0}',
'#page-academy .ss-primary{display:inline-flex;align-items:center;justify-content:center;min-height:43px;margin-top:12px;padding:10px 15px;border:0;border-radius:12px;background:#b9d4fb;color:#122033;font-weight:850;font-size:12px;cursor:pointer}',
'#page-academy .ss-secondary{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:9px 13px;border:1px solid #354861;border-radius:11px;background:#17263a;color:#d8e5f5;font-weight:750;font-size:11px;cursor:pointer}',
'#page-academy .ss-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:12px 0}',
'#page-academy .ss-course{display:flex;flex-direction:column;align-items:flex-start;text-align:left;min-height:155px;padding:14px;border:1px solid var(--ss-line);border-radius:17px;background:var(--ss-card);color:var(--ss-text);cursor:pointer}',
'#page-academy .ss-course:active,#page-academy .ss-primary:active,#page-academy .ss-secondary:active{transform:scale(.985)}',
'#page-academy .ss-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:#1e3047;color:#cbe0ff;font-size:17px;font-weight:900;margin-bottom:9px}',
'#page-academy .ss-course b{font-size:13px;line-height:1.25}',
'#page-academy .ss-course small{font-size:10px;color:var(--ss-muted);line-height:1.45;margin-top:5px}',
'#page-academy .ss-course .ss-course-foot{margin-top:auto;padding-top:10px;width:100%;font-size:10px;color:#c7d8ef}',
'#page-academy .ss-bar{height:5px;overflow:hidden;border-radius:30px;background:#29394d;margin-top:8px}',
'#page-academy .ss-bar i{display:block;height:100%;background:#b9d4fb;border-radius:30px}',
'#page-academy .ss-panel{padding:15px;border:1px solid var(--ss-line);border-radius:17px;background:var(--ss-card);margin:10px 0}',
'#page-academy .ss-panel h2{font-size:17px;line-height:1.25;margin:5px 0 8px}',
'#page-academy .ss-panel h3{font-size:13px;margin:0 0 6px}',
'#page-academy .ss-panel p{font-size:12px;line-height:1.65;color:#c1ccda;margin:6px 0}',
'#page-academy .ss-top{display:flex;align-items:center;justify-content:space-between;gap:9px;margin:2px 0 12px}',
'#page-academy .ss-back{border:1px solid #354861;border-radius:10px;background:#152338;color:#dce8f7;padding:9px 11px;font-size:11px;font-weight:800}',
'#page-academy .ss-meta{font-size:10px;color:var(--ss-muted)}',
'#page-academy .ss-lesson-list{display:grid;gap:7px;margin-top:12px}',
'#page-academy .ss-lesson{display:grid;grid-template-columns:30px minmax(0,1fr) auto;gap:9px;align-items:center;text-align:left;padding:11px;border:1px solid var(--ss-line);border-radius:13px;background:#0e1826;color:var(--ss-text);cursor:pointer}',
'#page-academy .ss-lesson-num{display:grid;place-items:center;width:29px;height:29px;border-radius:9px;background:#203148;color:#d4e4f8;font-size:10px;font-weight:900}',
'#page-academy .ss-lesson.done .ss-lesson-num{background:#183728;color:#9ce0b7}',
'#page-academy .ss-lesson b{font-size:11px;display:block}',
'#page-academy .ss-lesson small{font-size:9px;color:var(--ss-muted);display:block;margin-top:3px}',
'#page-academy .ss-lesson-status{font-size:9px;color:#b8cbe1}',
'#page-academy .ss-block{padding:13px 0;border-bottom:1px solid #26364b}',
'#page-academy .ss-block:last-child{border-bottom:0}',
'#page-academy .ss-block h3{font-size:13px;margin:0 0 6px}',
'#page-academy .ss-block p{margin:0;font-size:12px;line-height:1.68;color:#c6d1df}',
'#page-academy .ss-example{background:#17263a;border-left:3px solid #9fc5ff;padding:11px 12px;border-radius:0 11px 11px 0;margin:12px 0;font-size:11px;line-height:1.6;color:#dce8f7}',
'#page-academy .ss-q{padding:12px 0;border-bottom:1px solid #28394e}',
'#page-academy .ss-q:last-child{border-bottom:0}',
'#page-academy .ss-q b{font-size:12px;line-height:1.5}',
'#page-academy .ss-options{display:grid;gap:7px;margin-top:9px}',
'#page-academy .ss-choice{width:100%;text-align:left;padding:10px 11px;border:1px solid #34475f;border-radius:10px;background:#101b2a;color:#dce6f3;font-size:11px;line-height:1.45}',
'#page-academy .ss-choice.selected{border-color:#a9c9f5;background:#233852;color:#fff}',
'#page-academy .ss-feedback{font-size:11px;line-height:1.55;color:#c7d4e4;padding:9px 10px;margin-top:7px;background:#18263a;border-radius:9px}',
'#page-academy .ss-result{padding:12px;border-radius:12px;background:#172b40;border:1px solid #385271;color:#e3eefb;font-size:12px;line-height:1.5;margin-top:12px}',
'#page-academy .ss-note{font-size:10px;line-height:1.55;color:#aab9cc;margin:10px 1px}',
'#page-academy .ss-task{width:100%;min-height:104px;padding:11px;border-radius:11px;border:1px solid #354861;background:#0c1624;color:#eef3fa;font:inherit;font-size:12px;line-height:1.5}',
'#page-academy .ss-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}',
'#page-academy .ss-audio{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}',
'#page-academy .ss-source{display:inline-block;margin:7px 8px 0 0;color:#b9d4fb;font-size:11px;font-weight:750}',
'#page-academy .ss-small{font-size:10px;color:var(--ss-muted);line-height:1.5}',
'@media(max-width:560px){#page-academy .ss-grid{gap:8px}#page-academy .ss-course{min-height:145px;padding:12px}#page-academy .ss-panel{padding:13px}#page-academy .ss-lesson{grid-template-columns:29px minmax(0,1fr) auto;padding:10px 9px}}'
].join('');
if(!document.getElementById(styles.id))document.head.append(styles);
function course(id){return courses.find(c=>c.id===id)}
function lesson(courseId,lessonId){const c=course(courseId);return c&&c.lessons.find(l=>l.id===lessonId)}
function completedCount(c){return c.lessons.filter(l=>state.done[l.id]).length}
function nextLesson(c){return c.lessons.find(l=>!state.done[l.id])||c.lessons[c.lessons.length-1]}
function totalDone(){return courses.reduce((n,c)=>n+completedCount(c),0)}
function home(){
 const active=state.current&&lesson(state.current.courseId,state.current.lessonId)?state.current:null;
 const activeCourse=active?course(active.courseId):null;
 const last=activeCourse||(course(state.lastCourse)||course('icfes')),next=active?lesson(active.courseId,active.lessonId):(last?nextLesson(last):null);
 const done=totalDone(),total=courses.reduce((n,c)=>n+c.lessons.length,0);
 page.innerHTML='<div class="ss-wrap"><div class="ss-kicker">ADAZ · TU AULA</div><h1 class="ss-title">Aprende algo importante hoy.</h1><p class="ss-sub">Cuatro caminos. Lecciones breves. Todo ocurre aquí, dentro de ADAZ.</p>'+
 '<section class="ss-hero"><div class="ss-kicker">TU SIGUIENTE PASO</div><h2>'+(next?esc(next.title):'Elige qué quieres aprender')+'</h2><p>'+(next?(active?'Retoma donde lo dejaste en ':'Continúa en ')+esc(last.title)+' · '+next.time+' minutos aproximados.':'Selecciona una de las cuatro rutas para comenzar.')+'</p>'+(next?'<button class="ss-primary" data-studio-open="'+last.id+'" data-studio-lesson="'+next.id+'">'+(active?'Continuar lección →':'Empezar →')+'</button>':'')+'</section>'+
 '<div class="ss-grid">'+courses.map(c=>{const n=completedCount(c),pct=Math.round(n/c.lessons.length*100);return '<button class="ss-course" data-studio-course="'+c.id+'"><span class="ss-icon">'+c.icon+'</span><b>'+esc(c.title)+'</b><small>'+esc(c.desc)+'</small><div class="ss-course-foot">'+n+' de '+c.lessons.length+' lecciones</div><div class="ss-bar"><i style="width:'+pct+'%"></i></div></button>'}).join('')+'</div>'+
 '<section class="ss-panel"><div class="ss-top"><b>Tu avance</b><span class="ss-meta">'+done+' / '+total+' lecciones</span></div><div class="ss-bar"><i style="width:'+Math.round(done/total*100)+'%"></i></div><p class="ss-small">Tus prácticas anteriores siguen guardadas en ADAZ. Este nuevo espacio guarda el avance por separado para no alterar tu historial.</p></section>'+
 '<p class="ss-note">Las actividades de esta aula son material original de ADAZ. Las preguntas oficiales y los simulacros completos se consultan en sus plataformas de origen; nunca se presentan ejercicios inventados como oficiales.</p></div>';
}
function courseView(id){
 const c=course(id);if(!c){home();return}
 state.lastCourse=id;save();
 const n=completedCount(c),pct=Math.round(n/c.lessons.length*100),next=nextLesson(c);
 page.innerHTML='<div class="ss-wrap"><div class="ss-top"><button class="ss-back" data-studio-home>← Estudio</button><span class="ss-meta">'+n+' / '+c.lessons.length+' lecciones</span></div><div class="ss-kicker">TU RUTA DE APRENDIZAJE</div><h1 class="ss-title">'+esc(c.title)+'</h1><p class="ss-sub">'+esc(c.goal)+'</p>'+
 '<section class="ss-panel"><div class="ss-top"><b>Tu progreso</b><span class="ss-meta">'+pct+'%</span></div><div class="ss-bar"><i style="width:'+pct+'%"></i></div>'+(next?'<button class="ss-primary" data-studio-open="'+id+'" data-studio-lesson="'+next.id+'">Seguir con '+esc(next.title)+' →</button>':'<p>¡Has completado esta ruta! Puedes volver a cualquiera de sus lecciones para repasar.</p>')+'</section>'+
 '<div class="ss-lesson-list">'+c.lessons.map((l,i)=>'<button class="ss-lesson '+(state.done[l.id]?'done':'')+'" data-studio-open="'+id+'" data-studio-lesson="'+l.id+'"><span class="ss-lesson-num">'+(state.done[l.id]?'✓':String(i+1).padStart(2,'0'))+'</span><span><b>'+esc(l.title)+'</b><small>'+l.time+' min · '+(state.done[l.id]?'Completada':'Lección y práctica')+'</small></span><span class="ss-lesson-status">Abrir ›</span></button>').join('')+'</div>'+
 (c.official?'<div class="ss-panel"><b>Simulacro y material oficial</b><p>Cuando quieras practicar el formato auténtico, utiliza la fuente oficial además de estas lecciones.</p><a class="ss-source" href="'+c.official+'" target="_blank" rel="noopener noreferrer">Abrir recurso oficial ↗</a></div>':'')+
 (id==='business'?'<div class="ss-panel"><b>Material complementario para tu negocio</b><p>La Cámara de Comercio de Bogotá tiene recursos abiertos sobre costos, ventas y organización de emprendimientos. Las lecciones de ADAZ siguen estando aquí; estos enlaces son para profundizar.</p><a class="ss-source" href="https://catalogocampus.ccb.org.co/courses/ventas_negocio_pildoras_exito" target="_blank" rel="noopener noreferrer">Curso gratuito: ventas para un negocio pequeño ↗</a><a class="ss-source" href="https://bibliotecadigital.ccb.org.co/items/767756bf-c357-4560-9c20-a5eacb1e3e8f/full" target="_blank" rel="noopener noreferrer">Guía de costos y precios ↗</a></div>':'')+
 (id==='medicine'?'<div class="ss-panel"><b>Temario y libro abierto</b><p>MED500 publica áreas como anatomía, fisiología, histología, biología celular y bioquímica. Esta es una ruta propia de fundamentos de ADAZ; no es el curso MED500 ni está afiliada a Grupo 500.</p><a class="ss-source" href="https://hotmart.com/es/marketplace/productos/premedico-med500/J106297653T" target="_blank" rel="noopener noreferrer">Ver áreas públicas de MED500 ↗</a><a class="ss-source" href="https://openstax.org/details/books/anatomy-and-physiology-2e" target="_blank" rel="noopener noreferrer">OpenStax · Anatomy & Physiology 2e ↗</a></div>':'')+
 '<p class="ss-note">Las lecciones se pueden repetir. El objetivo es comprender y aplicar, no terminar rápido.</p></div>';
}
function lessonView(cid,lid){
 const c=course(cid),l=lesson(cid,lid);if(!c||!l){courseView(cid);return}
 if(!(state.current&&state.current.courseId===cid&&state.current.lessonId===lid))state.current=state.working[lid]||{courseId:cid,lessonId:lid,answers:{},checked:false,result:null};
 state.current.courseId=cid;state.current.lessonId=lid;state.working[lid]=state.current;
 state.lastCourse=cid;save();
 const current=state.current,done=!!state.done[lid];
 const index=c.lessons.indexOf(l)+1;
 const blocks=l.blocks.map(b=>'<div class="ss-block"><h3>'+esc(b[0])+'</h3><p>'+esc(b[1])+'</p></div>').join('');
 const questions=l.quiz.map((q,qi)=>'<div class="ss-q" data-ss-question="'+qi+'"><b>'+(qi+1)+'. '+esc(q.q)+'</b><div class="ss-options">'+q.opts.map((o,oi)=>'<button class="ss-choice '+(current.answers[qi]===oi?'selected':'')+(current.checked&&oi===q.a?' correct':current.checked&&current.answers[qi]===oi&&oi!==q.a?' wrong':'')+'" data-studio-answer="'+qi+'" data-choice="'+oi+'">'+String.fromCharCode(65+oi)+'. '+esc(o)+'</button>').join('')+'</div>'+(current.checked?'<div class="ss-feedback">'+(current.answers[qi]===q.a?'✓ Correcto. ':'Revisa esta idea. ')+esc(q.why)+'</div>':'')+'</div>').join('');
 const result=current.checked?'<div class="ss-result">Resultado: '+current.result+'/'+l.quiz.length+' correctas. '+(current.result===l.quiz.length?'¡Muy bien! Ya puedes guardar esta lección.':'Lee las explicaciones, cambia tus respuestas si hace falta y vuelve a comprobarlas.')+'</div>':'';
 const activity=l.audio?'<div class="ss-panel"><h3>Escucha y responde</h3><p>Este audio utiliza voz sintética del teléfono y un guion original de ADAZ; no es una grabación oficial del IELTS.</p><div class="ss-audio"><button class="ss-secondary" data-studio-speak>▶ Escuchar</button><button class="ss-secondary" data-studio-transcript>Ver el texto</button></div><p class="ss-small" id="ss-transcript" hidden>'+esc(l.audio)+'</p></div>':'';
 const writing=l.write?'<div class="ss-panel"><h3>Ahora te toca a ti</h3><p>Escribe unas ideas o una respuesta corta. Tu texto queda guardado en este dispositivo para que puedas volver a revisarlo.</p><textarea class="ss-task" data-studio-draft="'+lid+'" placeholder="Escribe aquí tu respuesta o tus ideas...">'+esc(state.drafts[lid]||'')+'</textarea><p class="ss-small">Revisa: ¿respondiste la consigna?, ¿las ideas están conectadas?, ¿usaste ejemplos o detalles precisos?</p></div>':'';
 page.innerHTML='<div class="ss-wrap"><div class="ss-top"><button class="ss-back" data-studio-course="'+cid+'">← '+esc(c.short)+'</button><span class="ss-meta">Lección '+index+' de '+c.lessons.length+' · '+l.time+' min</span></div><div class="ss-kicker">'+esc(c.title)+'</div><h1 class="ss-title">'+esc(l.title)+'</h1><p class="ss-sub">Lee la idea, mira el ejemplo y comprueba lo que entendiste.</p>'+
 '<section class="ss-panel">'+blocks+'</section><div class="ss-example"><b>Ejemplo:</b> '+esc(l.example)+'</div>'+activity+writing+
 '<section class="ss-panel"><div class="ss-kicker">PRÁCTICA RÁPIDA · ORIGINAL ADAZ</div><h2>Comprueba lo que aprendiste</h2><p>Elige una respuesta para cada pregunta. Al final verás por qué es correcta o qué debes revisar.</p>'+questions+
 '<div class="ss-actions"><button class="ss-primary" data-studio-check="'+lid+'">Comprobar respuestas</button><button class="ss-secondary" data-studio-reset>Volver a intentar</button></div>'+result+'</section>'+
 (current.checked?'<div class="ss-actions"><button class="ss-primary" data-studio-complete="'+lid+'">'+(done?'Lección guardada ✓':'Guardar y continuar →')+'</button></div>':'')+
 '<p class="ss-note">Este ejercicio sirve para aprender y practicar. No equivale a una nota oficial, una banda IELTS ni un resultado ICFES.</p></div>';
}
function checkAnswers(){
 const cur=state.current;if(!cur)return;
 const l=lesson(cur.courseId,cur.lessonId);if(!l)return;
 let score=0;for(let i=0;i<l.quiz.length;i++)if(cur.answers[i]===l.quiz[i].a)score++;
 cur.checked=true;cur.result=score;state.working[cur.lessonId]=cur;save();lessonView(cur.courseId,cur.lessonId);
}
function syncMainStudy(cid,lid,mins,score,max){
 const form=document.getElementById('studyForm');if(!form)return;
 const program=document.getElementById('studyProgram'),skill=document.getElementById('studySkill');
 const addOption=(select,value)=>{if(select&&!Array.from(select.options).some(o=>o.value===value||o.textContent===value)){const o=document.createElement('option');o.textContent=value;select.append(o)}};
 const p=cid==='business'?'Negocio':cid==='medicine'?'Medicina':cid==='icfes'?'ICFES':'IELTS';
 const l=lesson(cid,lid);if(!l)return;
 addOption(program,p);addOption(skill,l.title);
 const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v};
 set('studyProgram',p);set('studySkill',l.title);set('studyDate',today());set('studyMinutes',String(mins));
 set('studyAccuracy','');set('studyBand','');set('studyMethod','Lección interactiva');
 set('studyGoal',l.title);set('studyResult','Cuestionario original ADAZ: '+score+'/'+max+' respuestas correctas.');
 form.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));
}
function completeLesson(){
 const cur=state.current;if(!cur||!cur.checked)return;
 const l=lesson(cur.courseId,cur.lessonId);if(!l)return;
 const cid=cur.courseId,score=cur.result;
 state.done[l.id]={date:today(),score:score,attempts:(state.done[l.id]?.attempts||0)+1};
 delete state.working[l.id];state.current=null;save();
 syncMainStudy(cid,l.id,l.time,score,l.quiz.length);
 courseView(cid);
 const toast=document.getElementById('toast');if(toast){toast.textContent='Lección guardada. Tu avance quedó registrado.';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
}
function handleClick(e){
 const homeBtn=e.target.closest('[data-studio-home]');if(homeBtn){save();home();return}
 const cBtn=e.target.closest('[data-studio-course]');if(cBtn){courseView(cBtn.dataset.studioCourse);return}
 const open=e.target.closest('[data-studio-open]');if(open){lessonView(open.dataset.studioOpen,open.dataset.studioLesson);return}
 const choice=e.target.closest('[data-studio-answer]');if(choice&&state.current){const qi=Number(choice.dataset.studioAnswer),oi=Number(choice.dataset.choice);state.current.answers[qi]=oi;state.current.checked=false;state.current.result=null;state.working[state.current.lessonId]=state.current;save();const group=choice.closest('[data-ss-question]');group.querySelectorAll('[data-studio-answer]').forEach(b=>b.classList.toggle('selected',b===choice));page.querySelector('.ss-result')?.remove();page.querySelectorAll('.ss-feedback').forEach(n=>n.remove());const complete=page.querySelector('[data-studio-complete]');if(complete)complete.remove();return}
 const check=e.target.closest('[data-studio-check]');if(check){const l=state.current&&lesson(state.current.courseId,state.current.lessonId);if(!l)return;if(l.quiz.some((q,i)=>state.current.answers[i]===undefined)){const toast=document.getElementById('toast');if(toast){toast.textContent='Responde todas las preguntas primero.';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}return}checkAnswers();return}
 const reset=e.target.closest('[data-studio-reset]');if(reset&&state.current){state.current.answers={};state.current.checked=false;state.current.result=null;state.working[state.current.lessonId]=state.current;save();lessonView(state.current.courseId,state.current.lessonId);return}
 const complete=e.target.closest('[data-studio-complete]');if(complete){completeLesson();return}
 const speak=e.target.closest('[data-studio-speak]');if(speak&&state.current){const l=lesson(state.current.courseId,state.current.lessonId);if(l?.audio&&'speechSynthesis'in window){window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(l.audio);utterance.lang='en-US';utterance.rate=.88;window.speechSynthesis.speak(utterance)}else{const transcript=$('#ss-transcript');if(transcript)transcript.hidden=false}return}
 const transcript=e.target.closest('[data-studio-transcript]');if(transcript){const t=$('#ss-transcript');if(t)t.hidden=!t.hidden;return}
}
page.addEventListener('click',handleClick);
page.addEventListener('input',e=>{const draft=e.target.closest('[data-studio-draft]');if(draft){state.drafts[draft.dataset.studioDraft]=draft.value;save()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-page="academy"]'))setTimeout(home,130)});
window.addEventListener('adaz-data-updated',()=>{if(page.classList.contains('active')&&!state.current)home()});
window.addEventListener('adaz-experience-updated',()=>{if(page.classList.contains('active')&&!state.current)home()});
function simplifyRoutine(){
 const root=document.getElementById('page-routine');if(!root||root.dataset.rsReady)return;root.dataset.rsReady='1';
 const timeline=root.querySelector('#routineTimeline');
 if(timeline){
  timeline.classList.add('rs-timeline');
  const toggle=document.createElement('button');toggle.type='button';toggle.className='rs-more-btn';toggle.textContent='Ver todo el horario';toggle.setAttribute('aria-expanded','false');
  timeline.after(toggle);
  toggle.addEventListener('click',()=>{const on=timeline.classList.toggle('rs-expanded');toggle.textContent=on?'Mostrar menos':'Ver todo el horario';toggle.setAttribute('aria-expanded',String(on))});
  timeline.addEventListener('click',e=>{const item=e.target.closest('.routine-item');if(item)item.classList.toggle('rs-show-note')});
 }
 const reminderForm=root.querySelector('#reminderForm');
 if(reminderForm){
  const card=reminderForm.closest('.card'),header=card&&card.querySelector('.card-header');
  if(card&&header){
   const detail=document.createElement('details');detail.className='rs-reminder-details';
   const summary=document.createElement('summary');summary.textContent='Abrir recordatorios y alarmas';
   const body=document.createElement('div');body.className='rs-reminder-body';
   Array.from(card.childNodes).forEach(node=>{if(node!==header)body.append(node)});
   detail.append(summary,body);card.append(detail);
  }
 }
 const style=document.createElement('style');style.id='adaz-routine-simplifier-style';
 style.textContent=[
 '#page-routine .routine-hero{padding:16px 18px!important;margin-bottom:12px!important}',
 '#page-routine .routine-hero>p:not(:first-of-type){display:none}',
 '#page-routine .routine-hero h1{font-size:24px!important}',
 '#page-routine .routine-hero>p{font-size:11px!important;line-height:1.45}',
 '#page-routine .routine-timeline{gap:6px!important}',
 '#page-routine .routine-item{padding:9px 10px!important;grid-template-columns:90px minmax(0,1fr)!important;gap:8px!important}',
 '#page-routine .routine-body h3{font-size:11px!important;margin:0!important}',
 '#page-routine .routine-body p{display:none;font-size:10px!important;margin:4px 0 0!important}',
 '#page-routine .routine-item.rs-show-note .routine-body p{display:block}',
 '#page-routine .rs-timeline:not(.rs-expanded) .routine-item:nth-child(n+4){display:none}',
 '#page-routine .rs-more-btn{margin-top:10px;border:1px solid #354861;background:#17263a;color:#dce8f7;border-radius:10px;padding:9px 12px;font-size:10px;font-weight:800}',
 '#page-routine .rs-reminder-details{margin-top:9px;border:1px solid #29394f;border-radius:12px;padding:11px;background:#0e1724}',
 '#page-routine .rs-reminder-details summary{font-size:11px;font-weight:800;cursor:pointer;color:#c8d9ed}',
 '#page-routine .rs-reminder-body{padding-top:12px}',
 '#page-routine #routineTaskList .list-item{padding:6px 0!important}',
 '#page-routine #routineTaskList .list-item .muted{display:none}',
 '@media(max-width:820px){#page-routine .routine-item{grid-template-columns:78px minmax(0,1fr)!important}#page-routine .grid.two>.grid{gap:10px}}'
 ].join('');
 document.head.append(style);
}
function simplifyTraining(){
 const root=document.getElementById('adaz-strength-plan');if(!root||root.dataset.rsReady)return;root.dataset.rsReady='1';
 const stat=root.querySelector('.health-statrow');
 if(stat&&!root.querySelector('.rs-training-advice')){
  const note=document.createElement('div');note.className='routine-note rs-training-advice';
  note.innerHTML='<b>Cómo encajarla con natación:</b> son cuatro sesiones disponibles, no una obligación de completar todas si la piscina, el colegio o el descanso ya te exigen bastante. Distribúyelas con tu entrenador, deja recuperación entre los dos días de piernas y no recuperes sesiones perdidas acumulándolas. La técnica y el descanso mandan.';
  stat.after(note);
 }
 root.querySelectorAll('.routine-dose').forEach(node=>{
  node.innerHTML=node.innerHTML.replace(/2 × 6–10 por lado/g,'2 × 8–10 por lado').replace(/2 × 6–8 por lado/g,'2 × 8–10 por lado').replace(/2 × 6–10/g,'2 × 8–12').replace(/5 min/g,'2–3 min').replace(/2 min/g,'60–90 s');
 });
 root.querySelectorAll('.routine-row').forEach(row=>{
  const tip=row.querySelector('.routine-tip');if(!tip||row.querySelector('.rs-tip-toggle'))return;
  tip.hidden=true;
  const btn=document.createElement('button');btn.type='button';btn.className='rs-tip-toggle';btn.textContent='Ver indicación';
  btn.addEventListener('click',()=>{tip.hidden=!tip.hidden;btn.textContent=tip.hidden?'Ver indicación':'Ocultar indicación'});
  row.append(btn);
 });
 const style=document.createElement('style');style.id='adaz-training-simplifier-style';
 style.textContent='#adaz-strength-plan .routine-row{gap:7px!important}#adaz-strength-plan .routine-tip[hidden]{display:none!important}#adaz-strength-plan .routine-tip{font-size:10px!important;line-height:1.5}#adaz-strength-plan .rs-tip-toggle{justify-self:start;border:0;background:transparent;color:#b9d4fb;padding:4px 0;font-size:10px;font-weight:800}#adaz-strength-plan .routine-dose{font-size:11px!important}';
 document.head.append(style);
}
function addFuelGuide(){
 const root=document.getElementById('page-training');if(!root||root.querySelector('.adaz-fuel-guide'))return;
 const card=document.createElement('section');card.className='card section-gap adaz-fuel-guide';
 card.innerHTML='<div class="card-header"><div><h2>Alimentación para entrenar y recuperarte</h2><div class="card-sub">Ideas flexibles, sin dietas rígidas ni contar calorías.</div></div></div>'+
 '<p class="smalltext muted">Tu cuerpo necesita suficiente energía y variedad para estudiar, nadar, entrenar y recuperarse. No tienes que comer perfecto ni compensar lo que comiste.</p>'+
 '<div class="grid two"><div><b class="smalltext">En tus comidas principales</b><p class="smalltext muted">Combina una fuente de energía (arroz, papa, pasta, arepa, avena o pan), una fuente de proteína (huevos, lácteos, legumbres, pollo, pescado o alternativas), frutas o verduras y alguna grasa como aguacate, frutos secos o aceite de oliva.</p></div><div><b class="smalltext">Alrededor del entrenamiento</b><p class="smalltext muted">Si tienes hambre antes, una fruta con yogur, un sándwich o arepa con queso pueden ser opciones prácticas. Después, haz una comida o merienda completa y toma agua según sed, clima y duración del ejercicio.</p></div></div>'+
 '<div class="note">No incluimos metas de peso, calorías ni suplementos. Para ajustar la alimentación a tu crecimiento y a la carga de natación, consúltalo con tu familia y un profesional de nutrición deportiva pediátrica.</div>';
 root.append(card);
}
function init(){
 home();
 const program=document.getElementById('studyProgram');
 if(program){['Negocio','Medicina'].forEach(v=>{if(!Array.from(program.options).some(o=>o.textContent===v)){const o=document.createElement('option');o.textContent=v;program.append(o)}})}
 simplifyRoutine();simplifyTraining();addFuelGuide();
 document.addEventListener('click',e=>{
  if(e.target.closest('[data-page="routine"]'))setTimeout(simplifyRoutine,100);
  if(e.target.closest('[data-page="training"]'))setTimeout(()=>{simplifyTraining();addFuelGuide()},100);
 });
 const observer=new MutationObserver(()=>{simplifyTraining();addFuelGuide()});
 const train=document.getElementById('page-training');if(train)observer.observe(train,{childList:true,subtree:true});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();